import{z as B,x as d,o as E,c as p,q as s,j as o,D as r,d as t,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Karger 最小割","description":"","frontmatter":{"title":"Karger 最小割","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/karger-min-cut.md","filePath":"cs/karger-min-cut.md","lastUpdated":1791063341000}'),A={name:"cs/karger-min-cut.md"};function m(C,a,g,D,c,u){const n=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=s('<h1 id="karger-最小割" tabindex="-1">Karger 最小割 <a class="header-anchor" href="#karger-最小割" aria-label="Permalink to &quot;Karger 最小割&quot;">​</a></h1><div class="epigraph"><p>随机收缩边直到两点，得到的割以 $\\Omega(1/n^2)$ 概率为全局最小；重复 $O(n^2\\log n)$ 次高概率成功。</p><footer>—— 据 Karger, Global Min-cuts in RNC, 1993；Karger and Stein, 1996；CLRS 第 23 章对照整理</footer></div><p>上一课<a href="/cs/geometric-robustness">几何精度</a>收束几何。主干<a href="/cs/max-flow-ff">最大流最小割</a>是 \\(s\\)–\\(t\\) 割。全局最小割：无指定 \\(s,t\\)，无向边连通性。缺口是 Karger 随机收缩。不重写 Dinic。后课 Las Vegas / Monte Carlo 分类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无向（多重）图。收缩边：两端合并，环丢掉。直到剩 2 顶点，其间重边为割。最小割边数 \\(c\\)，成功概率 \\(\\ge 1/\\binom{n}{2}\\) 量级：每次收缩不碰最小割边的条件概率。Karger–Stein：递归到 \\(n/\\sqrt 2\\) 再分支，时间更好。</p><p><span class="marginnote">直觉类比：收缩边像把两座城市合并成「一个都市场」——桥还在，只是变成了市内桥。缩到只剩两个都市圈时，圈与圈之间剩下的几座桥就是候选割；全程没拆掉跨圈桥，这局就赢了。</span></p><p>缺口是随机收缩，不是 \\(n\\) 次最大流（也可 \\(O(n)\\) 次流，更重）。</p><h3 id="不是-–-最小割" tabindex="-1">不是 \\(s\\)–\\(t\\) 最小割 <a class="header-anchor" href="#不是-–-最小割" aria-label="Permalink to &quot;不是 $s$–$t$ 最小割&quot;">​</a></h3><p>全局割可小于某对 \\(s\\)–\\(t\\)。指定 \\(s,t\\) 用流。本课全局。</p><p><span class="marginnote">Karger 1993。Karger–Stein 1996。后课把成功概率收进 Monte Carlo 定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现用并查集 + 随机边（按重边权或邻接表）。重复独立试验取最小。Karger–Stein 递归写清分支。</p>',12)),(E(),o(l,null,{default:r(()=>[i(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%A4%9A%E9%87%8D%E5%9B%BE%22%5D%20--%3E%20CTR%5B%22%E9%9A%8F%E6%9C%BA%E6%94%B6%E7%BC%A9%22%5D%0A%20%20CTR%20--%3E%20CUT%5B%22%E4%B8%A4%E7%82%B9%E9%97%B4%E9%87%8D%E8%BE%B9%22%5D%0A%20%20CUT%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%E5%8F%96%E6%9C%80%E5%B0%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"加权边：按权随机，或先离散。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"最小割边少，随机边更常落在块内。分析用 \\(\\prod (1-c/(m_i))\\)。与最大流：确定多项式，常数大。Karger 简单、随机。与 Borůvka：都收缩，一个为 MST 最轻、一个为均匀随机。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"数字实例：\\(n=100\\) 时单次成功率约 \\(1/\\binom{100}{2} \\approx 0.02\\%\\)，看似没救；但独立跑 2 万次，全败概率约 \\((1-1/4950)^{20000} \\approx e^{-4} \\approx 1.8\\%\\)，跑 5 万次降到约 \\(0.004\\%\\)——重复独立试验是 Karger 唯一的放大器。")],-1)),(E(),o(l,null,{default:r(()=>[i(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%89%A9%20k%20%E4%B8%AA%E9%A1%B6%E7%82%B9%E6%97%B6%E9%9A%8F%E6%9C%BA%E6%94%B6%E7%BC%A9%E4%B8%80%E6%9D%A1%E8%BE%B9%22%5D%20--%3E%20Q%5B%22%E8%BF%99%E6%9D%A1%E8%BE%B9%E6%9C%89%E5%A4%9A%E5%8D%B1%E9%99%A9%EF%BC%9F%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E6%9C%80%E5%B0%8F%E5%89%B2%E5%85%B1%20c%20%E6%9D%A1%E8%BE%B9%EF%BC%8C%E5%9B%BE%E9%87%8C%E8%87%B3%E5%B0%91%E8%BF%98%E6%9C%89%20k%C2%B7c%2F2%20%E6%9D%A1%E8%BE%B9%22%5D%0A%20%20B%20--%3E%20A%5B%22%E6%8A%BD%E4%B8%AD%E6%9C%80%E5%B0%8F%E5%89%B2%E8%BE%B9%E7%9A%84%E6%A6%82%E7%8E%87%20%E2%89%A4%202%2Fk%22%5D%0A%20%20A%20--%3E%20OK%5B%22%E4%B8%8D%E7%A2%B0%E6%9C%80%E5%B0%8F%E5%89%B2%E7%9A%84%E6%A6%82%E7%8E%87%20%E2%89%A5%201%20%E2%88%92%202%2Fk%22%5D%0A%20%20OK%20--%3E%20CH%5B%22%E4%BB%8E%20k%3Dn%20%E4%B8%80%E8%B7%AF%E4%B9%98%E5%88%B0%20k%3D3%22%5D%0A%20%20CH%20--%3E%20E%5B%22%E5%8D%95%E6%AC%A1%E5%AD%98%E6%B4%BB%E7%8E%87%20%E2%89%A5%202%2F(n(n%E2%88%921))%EF%BC%8C%E5%8D%B3%201%2FC(n%2C2)%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写近线性确定全局最小割的最新结果全文。有向全局割不同。后课默认：全局最小割可用随机收缩。下一课 Las Vegas 与 Monte Carlo。</p><p><span class="marginnote">常见误区：以为「随机算法」就不可信。Karger 是 Monte Carlo 型——输出偶有错，但重复能把错误概率压到任意小；而且拿到一个割后，检查它是否连通只需一次遍历，答案的好坏可以廉价验证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机收缩以多项式分之一得到最小割。</li><li>重复放大成功概率。</li><li>全局，不是 \\(s\\)–\\(t\\)。</li><li>出处：Karger, 1993；Karger and Stein, 1996。</li></ul>',5))])}const k=B(A,[["render",m]]);export{f as __pageData,k as default};
